import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Vehicle> fleet = new ArrayList<>();     // starts empty, grows as needed
        fleet.add(new Jeepney("NXA 123", "Mang Ramon", "Monumento-Divisoria"));
        fleet.add(new Tricycle("TRC 456", "Kuya Ben", "Bagong Silang TODA"));
        fleet.add(new Bus("BUS 789", "Aling Rosa", 50));
        fleet.add(new Jeepney("NYB 321", "Mang Tonyo", "Sangandaan-Recto"));   // a 4th!

        System.out.println("Vehicles in fleet: " + fleet.size());
        System.out.println("First vehicle: " + fleet.get(0).getPlateNumber());

        fleet.remove(1);                             // the tricycle leaves for repair
        System.out.println("After removal: " + fleet.size());

        for (Vehicle v : fleet) {
            v.showInfo();
        }

        try {
            fleet.get(5).showInfo();                 // there is no index 5
        } catch (IndexOutOfBoundsException e) {
            System.out.println("No vehicle there: index 5 is unavailable.");
        }
    }
}

import java.util.LinkedList;

public class Main {
    public static void main(String[] args) {
        LinkedList<String> line = new LinkedList<>();            // passengers waiting at the terminal
        line.addLast("Ana");
        line.addLast("Ben");
        line.addLast("Carla");
        line.addFirst("Lolo Pedro");                             // senior citizen: priority lane

        System.out.println("Waiting: " + line);
        System.out.println("Next to board: " + line.getFirst());

