import java.util.HashSet;
import java.util.Set;
import java.util.TreeSet;

public class Main {
    public static void main(String[] args) {
        String[] passedBy = { "Monumento", "Recto", "5th Avenue", "Blumentritt",
                              "Divisoria", "Recto", "Monumento" };

        Set<String> hashStops = new HashSet<>();
        TreeSet<String> treeStops = new TreeSet<>();              // TreeSet keeps them SORTED
        for (String stop : passedBy) {
            hashStops.add(stop);
            treeStops.add(stop);
        }

        System.out.println("Stops passed: " + passedBy.length);
        System.out.println("Different stops: " + treeStops.size());
        System.out.println("TreeSet, sorted: " + treeStops);
        System.out.println("First alphabetically: " + treeStops.first());
        System.out.println("Last alphabetically: " + treeStops.last());
        System.out.println("HashSet: " + hashStops);
    }
}

