import java.util.HashMap;
import java.util.Map;

public class Main {
    // look up a vehicle by plate; throws our custom exception if it is not there
    static Vehicle findVehicle(Map<String, Vehicle> byPlate, String plate)
            throws VehicleNotFoundException {
        if (!byPlate.containsKey(plate)) {
            throw new VehicleNotFoundException("No vehicle with plate " + plate);
        }
        return byPlate.get(plate);
    }

    public static void main(String[] args) {
        Map<String, Vehicle> byPlate = new HashMap<>();     // key: plate, value: the vehicle
        byPlate.put("NXA 123", new Jeepney("NXA 123", "Mang Ramon", "Monumento-Divisoria"));
        byPlate.put("TRC 456", new Tricycle("TRC 456", "Kuya Ben", "Bagong Silang TODA"));
        byPlate.put("BUS 789", new Bus("BUS 789", "Aling Rosa", 50));

        System.out.println("Vehicles on record: " + byPlate.size());
        byPlate.get("BUS 789").showInfo();                  // instant lookup by key
        System.out.println("Has ZZZ 000? " + byPlate.containsKey("ZZZ 000"));
        System.out.println("get(\"ZZZ 000\") gives: " + byPlate.get("ZZZ 000"));

        try {
            findVehicle(byPlate, "TRC 456").showInfo();
            findVehicle(byPlate, "ZZZ 000").showInfo();     // not found
        } catch (VehicleNotFoundException e) {
            System.out.println("Lookup failed: " + e.getMessage());
        }
    }
}

import java.util.Map;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) {
        Map<String, Integer> trips = new TreeMap<>();          // key: driver, value: trips today
        trips.put("Mang Ramon", 5);
        trips.put("Kuya Ben", 8);
        trips.put("Aling Rosa", 3);

        trips.put("Kuya Ben", trips.get("Kuya Ben") + 1); // same key: the value is REPLACED
        trips.put("Mang Tonyo", trips.getOrDefault("Mang Tonyo", 0) + 1);

        System.out.println("Drivers: " + trips.size());
        for (Map.Entry<String, Integer> entry : trips.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue() + " trip(s)");
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Vehicle> fleet = new ArrayList<>();
        fleet.add(new Jeepney("NXA 123", "Mang Ramon", "Monumento-Divisoria"));
        fleet.add(new Tricycle("TRC 456", "Kuya Ben", "Bagong Silang TODA"));
        fleet.add(new Bus("BUS 789", "Aling Rosa", 50));
        fleet.get(1).setPassengers(3);

        // LOOP 1: index for loop (lists only) - you get the position number
        for (int i = 0; i < fleet.size(); i++) {
            System.out.println((i + 1) + ". " + fleet.get(i).getPlateNumber());
        }

        // LOOP 2: for-each loop (any collection) - shortest, read-only
        double total = 0;
        for (Vehicle v : fleet) {
            total = total + v.quoteFare(5);
        }
        System.out.println("Total fare for 5 km on every vehicle: P" + total);
    }
}

