import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Vehicle> fleet = new ArrayList<>();
        fleet.add(new Jeepney("NXA 123", "Mang Ramon", "Monumento-Divisoria"));
        fleet.add(new Tricycle("TRC 456", "Kuya Ben", "Bagong Silang TODA"));
        fleet.add(new Bus("BUS 789", "Aling Rosa", 50));
        fleet.get(1).setPassengers(3);

        // LOOP 3: Iterator - the SAFE way to remove while looping
        Iterator<Vehicle> it = fleet.iterator();
        while (it.hasNext()) {
            Vehicle v = it.next();
            if (v.getPassengers() == 0) {
                it.remove();                      // remove through the iterator
                System.out.println("Off duty: " + v.getPlateNumber());
            }
        }
        System.out.println("Vehicles still on duty: " + fleet.size());
    }
}

import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

public class Main {
    public static void main(String[] args) {
        Set<String> stops = new TreeSet<>();
        stops.add("Recto");
        stops.add("Monumento");
        stops.add("Divisoria");
        for (String stop : stops) {
            System.out.println("Stop: " + stop);
        }

        Map<String, Integer> trips = new TreeMap<>();
        trips.put("Mang Ramon", 5);
        trips.put("Kuya Ben", 9);
        trips.put("Aling Rosa", 3);

        for (String driver : trips.keySet()) {
            System.out.print(driver + " ");          // keys
        }
        System.out.println();
        int total = 0;
        for (int count : trips.values()) {           // values
            total = total + count;
        }
        System.out.println("Total trips: " + total);
        for (Map.Entry<String, Integer> e
                : trips.entrySet()) {                // both
            System.out.println(e.getKey() + " -> "
                + e.getValue());
        }
    }
}

public class ProductNotFoundException extends Exception {      // CHECKED
    public ProductNotFoundException(String message) {
        super(message);
    }
}

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

public class Main {
    // FIND: look up a product by name; throws our own checked exception
    static int findStock(Map<String, Integer> stock, String name) throws ProductNotFoundException {
        if (!stock.containsKey(name)) {
            throw new ProductNotFoundException("No product named " + name);
        }
        return stock.get(name);
    }

    public static void main(String[] args) {
        // MAP: product name -> pieces in stock (TreeMap: report comes out A to Z)
        Map<String, Integer> stock = new TreeMap<>();
        stock.put("Softdrink", 24);
        stock.put("Bread", 10);
        stock.put("Rice (kg)", 50);
        stock.put("Candy", 0);

        // LIST: every sale, in order, repeats allowed
        List<String> salesLog = new ArrayList<>();
        salesLog.add("Ana bought 2 Bread");
        salesLog.add("Ben bought 1 Softdrink");
        salesLog.add("Ana bought 1 Softdrink");

        // SET: each customer counted once (TreeSet: names A to Z)
        Set<String> customers = new TreeSet<>();
        System.out.println("Ana added? " + customers.add("Ana"));
        System.out.println("Ben added? " + customers.add("Ben"));
        System.out.println("Ana added again? " + customers.add("Ana"));   // false: refused

        // LOOP 1: index for loop numbers the sales
        for (int i = 0; i < salesLog.size(); i++) {
            System.out.println((i + 1) + ". " + salesLog.get(i));
        }

        // LOOP 2: for-each adds up the stock
        int pieces = 0;
        for (int count : stock.values()) {
            pieces = pieces + count;
        }
        System.out.println("Pieces in stock: " + pieces);
        System.out.println("Different customers: " + customers);

        // LOOP 3: Iterator removes the sold-out items safely
        Iterator<Map.Entry<String, Integer>> it = stock.entrySet().iterator();
        while (it.hasNext()) {
            Map.Entry<String, Integer> e = it.next();
            if (e.getValue() == 0) {
                System.out.println("Sold out, removed: " + e.getKey());
                it.remove();
            }
        }

        // MAP LOOP with entrySet()
        for (Map.Entry<String, Integer> e : stock.entrySet()) {
            System.out.println(e.getKey() + " -> " + e.getValue());
        }

        // LOOKUP: a missing key shows a friendly message, never a crash
        String[] wanted = { "Bread", "Eggs" };
        for (String key : wanted) {
            try {
                System.out.println(key + " in stock: " + findStock(stock, key));
            } catch (ProductNotFoundException e) {
                System.out.println("Sorry: " + e.getMessage());
            } finally {
                System.out.println("Search finished.");
            }
        }
    }
}

